-- «تغذية البيانات» → trained questions and answers for «اسأل نايوش», and the questions it could not answer yet.
CREATE TABLE qa_entries (
  id         INTEGER PRIMARY KEY,
  question   TEXT NOT NULL,
  variants   TEXT NOT NULL DEFAULT '[]',
  answer     TEXT NOT NULL,
  category   TEXT,
  keywords   TEXT,
  link       TEXT,
  active     INTEGER NOT NULL DEFAULT 1,
  uses       INTEGER NOT NULL DEFAULT 0,
  created_by INTEGER REFERENCES users(id),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE qa_unanswered (
  id         INTEGER PRIMARY KEY,
  norm       TEXT NOT NULL UNIQUE,
  question   TEXT NOT NULL,
  count      INTEGER NOT NULL DEFAULT 1,
  user_id    INTEGER REFERENCES users(id),
  first_at   TEXT NOT NULL,
  last_at    TEXT NOT NULL
);
INSERT INTO qa_entries (question, variants, answer, category, keywords, link, created_at, updated_at) VALUES
 ('ما هي نايوش؟', '["عرفني على نايوش","شو هي منظومة نايوش","ما هي منظومة نايوش للتحليل"]', 'نايوش منظومة تحليل تساعد المؤسسات والأفراد على فهم المشكلة واتخاذ القرار بناءً على البيانات: تختار محور التحليل، ترفع بياناتك، ويصلك تقرير موثّق بالنتائج والتوصيات. القرار دائمًا لك.', 'عن نايوش', 'نايوش,منظومة', 'info', datetime('now'), datetime('now')),
 ('كيف أطلب تحليلًا؟', '["كيف اطلب تحليل بيانات","طريقة طلب التحليل","بدي اعمل طلب تحليل"]', 'من «محاور التحليل» اختر الموضوع واضغط «طلب تحليل». يفتح النموذج جاهزًا بالموضوع؛ أرفق ملف بياناتك (Excel أو CSV أو غيره)، وافق على سياسة الخصوصية وأرسل. تتابع المراحل في «طلباتي وتقاريري».', 'الطلبات', 'طلب,تحليل,نموذج', 'axes', datetime('now'), datetime('now')),
 ('كم تكلفة طلب التحليل؟', '["كم سعر التحليل","كم نقطة يحتاج الطلب","تكلفة الطلب"]', 'يُخصم من رصيدك عدد النقاط المحدد للطلب عند الإرسال، ويُسترد تلقائيًا إذا رُفض الطلب. تظهر التكلفة ورصيدك قبل الإرسال مباشرة.', 'النقاط والدفع', 'تكلفة,سعر,نقاط', 'hub', datetime('now'), datetime('now')),
 ('كيف أشحن رصيدي؟', '["كيف اشحن نقاط","شحن الرصيد","اريد شراء نقاط"]', 'اضغط «اشحن رصيدك» أعلى الصفحة، اختر الباقة وطريقة الدفع، ويمكنك إدخال كود خصم إن وجد. الرصيد لا ينتهي بمدة.', 'النقاط والدفع', 'شحن,رصيد,باقة', 'hub', datetime('now'), datetime('now')),
 ('ما أنواع الملفات التي يمكنني رفعها؟', '["ما الملفات المقبولة","هل اقدر ارفع صور او فيديو","صيغ الملفات"]', 'يمكنك رفع أي ملف: Excel وCSV وPDF وWord وصور وفيديو. جداول البيانات (Excel وCSV) يبدأ تحليلها آليًا فورًا، وباقي الملفات يراجعها فريق التحليل ويُصدر تقريرك.', 'الطلبات', 'ملفات,رفع,صور,فيديو,اكسل', '', datetime('now'), datetime('now')),
 ('كم يستغرق التحليل؟', '["متى يجهز التقرير","مدة التحليل","كم وقت ياخذ التحليل"]', 'التحليل الآلي لجداول البيانات يكتمل خلال دقائق من استلام الملف. الطلبات التي تحتوي صورًا أو مستندات فقط يراجعها فريق التحليل، ويصلك إشعار حين يجهز التقرير.', 'الطلبات', 'مدة,وقت,متى', 'myreqs', datetime('now'), datetime('now')),
 ('كيف أتحقق من أصالة التقرير؟', '["هل التقرير اصلي","التحقق من التقرير","رمز التحقق"]', 'كل تقرير يحمل رمز تحقق أسفل كل صفحة. افتح «التحقق من تقرير» واكتب الرمز، ويمكنك اختيار ملف PDF لمقارنة بصمته بالنسخة الأصلية المحفوظة لدى نايوش.', 'التقارير', 'تحقق,اصالة,رمز', 'verify', datetime('now'), datetime('now')),
 ('هل بياناتي آمنة؟', '["الخصوصية","من يرى بياناتي","هل تشاركون بياناتي"]', 'بياناتك لا يراها إلا أنت والمصرّح لهم من فريق نايوش حسب أدوارهم، وكل وصول مسجّل في سجل تدقيق لا يمكن تعديله. لا نبيع بياناتك ولا نشاركها دون موافقتك.', 'الخصوصية', 'خصوصيه,امان,بيانات', 'info', datetime('now'), datetime('now'));
